export type EquationGuide = { equation: string; symbols: string; meaning: string; reasoning: string; conditions: string; check: string };
export type GuidedLessonData = { prerequisites: string; opening: string; sections: {title:string; paragraphs:string[]}[]; models: EquationGuide[]; graph: string; examples:{prompt:string;steps:string[]}[]; questions:{prompt:string;choices:string[];correct:number;explanation:string}[]; reasoning:{prompt:string;answer:string}[]; checklist:string[] };
const section=(title:string,...paragraphs:string[])=>({title,paragraphs});
const model=(equation:string,symbols:string,meaning:string,reasoning:string,conditions:string,check:string)=>({equation,symbols,meaning,reasoning,conditions,check});
const example=(prompt:string,...steps:string[])=>({prompt,steps});
const question=(prompt:string,choices:string[],correct:number,explanation:string)=>({prompt,choices,correct,explanation});
const written=(prompt:string,answer:string)=>({prompt,answer});
export const guidedLessons: Record<string,GuidedLessonData> = {
'2.1': {
 prerequisites:'From Unit 1: position, signed components, and average velocity. A weighted average gives unequal contributions different importance.',
 opening:'Two astronauts pull on a rope between them. Each astronaut accelerates, but does that mean their combined system accelerates? The answer depends on which objects are inside your boundary and which interactions cross it.',
 sections:[section('Choose the system before choosing an equation','A system is the object or collection of objects you decide to study. Draw a boundary around it. Everything else is the surroundings. A force is external when the interacting source is outside that boundary. A force between two included objects is internal. The same interaction can therefore be internal for one choice of system and external for another.','For two carts linked by a light spring, the spring interaction is external when studying one cart; it is internal when studying the carts and spring together. Gravity and track forces are still external to that larger system. Choose a system that lets the unknown internal forces cancel when you want the overall motion.'),section('Why a centre of mass is useful','The centre of mass is a single position that represents the distribution of mass. It is not necessarily a material point: a ring has its centre of mass in the empty middle. For two masses it lies on the line between them, closer to the larger mass. Equal masses give the midpoint.','Treat an extended object as a point at its centre of mass when its size and rotation are not relevant to the translational question. That simplification does not erase the object’s real size; it focuses on one aspect of its motion.'),section('Internal motion versus motion of the whole system','Internal forces can change individual motions while cancelling in the vector sum for the whole system. With zero net external force, the centre-of-mass velocity stays constant. If initially at rest it stays at rest, even while the objects move apart.','For each coordinate, mass-weighted positions and velocities use the same weights. Moving the origin changes all position coordinates and the centre-of-mass coordinate by the same amount; it does not change the physical point represented.')],
 models:[model('x_cm = Σ(m_i x_i) / Σm_i','m_i: mass of part i (kg); x_i: its position (m); Σ: add over every included part; x_cm: centre-of-mass position (m).','Multiply each position by its mass so that more massive parts contribute more strongly, then divide by total mass.','For two masses, write Mx_cm = m₁x₁ + m₂x₂ with M = m₁ + m₂. Solving for x_cm yields the weighted average. Repeat with y or z for other coordinates.','Use one coordinate system and include every significant mass in the chosen system. A uniform symmetric object has its centre of mass at its geometric centre.','The numerator has units kg·m and the denominator kg, leaving m. If m₂ dominates, x_cm approaches x₂.'),model('ΣF_external = M a_cm','M: total mass (kg); a_cm: centre-of-mass acceleration (m/s²); external forces in N.','External interactions determine the translation of the whole system.','Add Newton’s second-law equations for all parts. Equal and opposite internal force pairs cancel; the mass-weighted accelerations give M a_cm.','An inertial frame and fixed total mass. Internal forces may still deform the system or alter relative motion.','Zero external net force gives constant centre-of-mass velocity, not necessarily stationary parts.')],
 graph:'On a position diagram, put every mass on the same numbered axis before computing x_cm. A centre-of-mass position–time graph has slope v_cm. A straight line indicates constant centre-of-mass velocity even if individual paths are curved.',
 examples:[example('A 2 kg cart is at −1 m and a 6 kg cart is at +3 m. Locate the centre of mass.','Choose right positive and keep the stated origin. Total mass is 8 kg.','x_cm = [2(−1) + 6(3)]/8 = 2 m.','It lies between the carts and closer to the 6 kg cart. It is not the midpoint (+1 m).'),example('Two astronauts, initially at rest, pull each other together in deep space. What happens to their centre of mass?','Choose both astronauts and the rope as the system; neglect external forces.','The internal pulls cancel in the total force sum, so a_cm = 0.','Because v_cm initially equals zero, its position stays fixed. Each astronaut moves toward that position; the lighter one accelerates more.')],
 questions:[question('Masses m and 3m lie at x = 0 and x = 8 m. Where is their centre of mass?',['2 m','4 m','6 m','8 m'],2,'x_cm = (m·0 + 3m·8)/(4m) = 6 m. The midpoint ignores the unequal masses.'),question('Two carts repel using a compressed spring. With negligible external horizontal force, what remains constant?',['Each cart’s velocity','Their separation','Their centre-of-mass velocity','Each cart’s acceleration'],2,'The internal spring forces cancel for the combined system. Only its centre-of-mass velocity is constrained to remain constant.')],
 reasoning:[written('Error analysis: “There are forces on each cart, so the centre of mass must accelerate.” Explain the missing distinction.','Acceleration of the centre of mass depends on the net external force. The spring exerts equal and opposite internal forces on the included carts, which cancel in the combined force sum. Individual accelerations can be nonzero while a_cm = 0.'),written('Challenge: masses 2 kg and 6 kg have positions x₁ = 1 + 3t and x₂ = 5 − t, with positions in metres and t in seconds. Find x_cm(t).','x_cm = [2(1 + 3t) + 6(5 − t)]/8 = 4 m. The time terms cancel, so the centre of mass is stationary although both carts move.')],
 checklist:['Draw a useful system boundary and classify interactions.','Calculate a mass-weighted position with signed coordinates.','Distinguish individual motion from centre-of-mass motion.']},
'2.2': {
 prerequisites:'Vector components from Unit 1; the system boundary from Topic 2.1. A force is an interaction, not a property stored by a moving object.',
 opening:'A book rests on a table. It is stationary, yet the Earth and table both exert forces on it. A free-body diagram records those interactions so we can explain the motion rather than guess from appearances.',
 sections:[section('Name the interacting objects','A force is a push or pull on a chosen object by another object. Contact forces include normal force, friction, tension, and spring force. Gravity acts without direct contact. Write force names as “force of source on object” so their origin is clear.','Mass measures inertia in kilograms. Weight is the gravitational force in newtons. Motion is not a force: do not add a “force of motion” to your diagram.'),section('Build a free-body diagram','Isolate one object or system and replace it by a dot or simple outline. Draw only external forces acting on it, with arrows starting on the isolated object. Label each source and direction. Arrow lengths can indicate relative magnitudes when known; otherwise label the drawing schematic.','The normal force is perpendicular to the contact surface. Tension pulls along a taut string away from the object. Friction is parallel to contact and opposes relative sliding or its tendency. Gravity points toward Earth’s centre, approximately down in a small near-surface diagram.'),section('Resolve forces without double counting','Choose axes to simplify the problem. On an incline, axes parallel and perpendicular to the surface often avoid resolving the normal force. Weight then has parallel component mg sinθ down the incline and perpendicular component mg cosθ into it.','Components replace a vector for calculating a sum; they are not additional physical forces. Either draw the original weight arrow or a separate component diagram. Never add mg together with both of its components in the same net-force calculation.'),section('Constraints do not mean all forces are equal','An object staying on a horizontal surface has zero vertical acceleration, so vertical forces balance. It may still accelerate horizontally. A pulling force angled upward can reduce the normal force; pushing down can increase it. The normal force is not automatically equal to weight.')],
 models:[model('ΣF_x = F₁x + F₂x + …; ΣF_y = F₁y + F₂y + …','F_x and F_y: signed force components in N; Σ: vector-component sum.','The net force combines every external interaction component by component.','If an applied pull F is θ above +x, its components are F cosθ and F sinθ. Vertical balance on a level floor gives N + F sinθ − mg = 0.','Axes and angles must be specified. Balance applies only along a direction with zero acceleration.','N = mg − F sinθ predicts a smaller normal force for an upward pull; if N would be negative, contact is lost and the assumed model fails.')],
 graph:'A free-body diagram is a force representation, not a trajectory. A rightward velocity does not require a rightward force. When drawing on an incline, show the surface angle and chosen axes; read the right triangle to justify sine and cosine.',
 examples:[example('A 4 kg box is pulled horizontally by 20 N while sliding friction is 6 N. Draw its FBD on a level floor. Use g = 9.8 m/s².','Include Earth’s weight 39.2 N down, floor normal 39.2 N up, applied pull 20 N right, and friction 6 N left.','Vertical acceleration is zero, so normal and weight balance. Horizontal net force is 20 − 6 = 14 N right.','Do not add a separate acceleration arrow as a force.'),example('A 5 kg box is pulled with 20 N at 30° above a level surface. Find N while it remains in contact.','Resolve the applied pull: upward component = 20sin30° = 10 N.','Vertical balance: N + 10 − 49 = 0. Thus N = 39 N.','The floor supplies less upward force because the rope supplies some. Normal is not 49 N.')],
 questions:[question('A box slides right on a rough horizontal floor with no applied horizontal force. Which horizontal force belongs on its FBD?',['A rightward force of motion','Leftward kinetic friction','Rightward acceleration','A forward weight component'],1,'The floor exerts kinetic friction opposite relative sliding. Velocity and acceleration are descriptions of motion, not interactions.'),question('A block rests on a frictionless incline. The normal force is directed…',['Vertically upward','Parallel uphill','Perpendicular away from the incline','Toward Earth’s centre'],2,'Normal describes the direction perpendicular to the contact surface. Weight points toward Earth; those directions differ on an incline.')],
 reasoning:[written('Error analysis: A diagram includes weight down, normal up, and a second arrow down labelled “reaction to the normal force.” Correct it.','The reaction partner to normal is the block’s force on the surface and acts on the surface, not on the block. A one-object FBD contains only forces acting on that object. Weight is a different interaction with Earth.'),written('Create a representation: describe an FBD for a hanging mass on a taut vertical string.','Draw the mass as a dot. Draw tension upward along the string and weight mg downward. For rest or constant velocity they have equal magnitudes. If accelerating, their lengths must reflect the net force rather than being assumed equal.')],
 checklist:['Identify a source for each force.','Draw only forces on the chosen object.','Use axes, components, and contact constraints consistently.']},
'2.3': {
 prerequisites:'Object-by-object free-body diagrams from Topic 2.2. Keep track of which object receives each force.',
 opening:'A small car collides with a heavy truck. The forces between them have equal magnitudes, even though the car can have the larger acceleration. Equal interaction forces do not mean equal effects on unequal masses.',
 sections:[section('One interaction, two forces','If object A exerts a force on B, then B simultaneously exerts an equal-magnitude, opposite-direction force on A. These are two descriptions of the same interaction. They exist for both contact and gravitational interactions and do not depend on whether either object is moving.','The pair acts on different objects. Therefore the two forces do not cancel in the force sum for one object. They cancel as internal forces only when both objects are included in the same system.'),section('Identify the partner by swapping source and receiver','“Earth on book” pairs with “book on Earth.” “Table on book” pairs with “book on table.” Weight and normal on the book can balance, but they are not a third-law pair because both act on the book and come from different interactions.','During a collision, the forces match instant by instant. Different accelerations follow from different masses: a = F_net/m. Additional forces may affect either object’s total acceleration.'),section('Apply the law to connected objects','A light taut string over an ideal pulley has the same tension magnitude throughout, but tension forces on two different objects are not automatically each other’s third-law pair. Each object interacts with the string. The equal tension follows from the negligible mass and ideal pulley assumptions.','For two touching blocks pushed together, the contact pair links their equations. Analyse the combined system first to find acceleration, then one block to find the internal contact force.')],
 models:[model('F⃗_A on B = −F⃗_B on A','Each force is a vector in N; the minus sign reverses direction, not magnitude.','Interaction partners exchange equal and opposite forces at the same time.','Write separate equations for A and B. When adding them for a combined system, these two internal terms sum to zero.','The partners must be the same interaction with source and receiver reversed. Their other forces need not be equal.','The pair remains equal even if A is much more massive or accelerates less than B.')],
 graph:'Draw two separate FBDs, one per object, and mark matching interaction arrows with the same colour or label. Place each arrow on the object it acts on. Comparing arrow lengths tests equal forces; comparing acceleration arrows tests force divided by mass.',
 examples:[example('Two blocks of masses 2 kg and 3 kg touch on a frictionless floor. A 10 N force pushes the 2 kg block toward the 3 kg block. Find contact force.','For the combined 5 kg system, internal contact forces cancel. a = 10/5 = 2 m/s².','The 3 kg block has one horizontal force: contact C. C = 3(2) = 6 N right.','It exerts 6 N left on the 2 kg block. That block’s net force is 10 − 6 = 4 N, giving the same 2 m/s² acceleration.'),example('Earth pulls a falling apple with 1 N. How large is the apple’s force on Earth?','Identify the same gravitational interaction with source and receiver reversed.','The apple pulls Earth with 1 N toward the apple.','Earth’s acceleration is extremely small because Earth’s mass is extremely large, not because its interaction force is smaller.')],
 questions:[question('A 1 kg cart and a 4 kg cart push each other. With no other horizontal forces, how do their acceleration magnitudes compare?',['Equal','The 1 kg cart accelerates four times as much','The 4 kg cart accelerates four times as much','Neither accelerates'],1,'The forces have equal magnitudes. Dividing by mass gives a_small/a_large = 4.'),question('The third-law partner of the floor’s friction force on a sliding box is…',['Earth’s weight on the box','The box’s friction force on the floor','The floor’s normal force on the box','A force of motion on the box'],1,'Swap source and receiver for the same friction interaction. The partner acts on the floor.')],
 reasoning:[written('Error analysis: “The truck applies more force because it is heavier.” Explain the collision forces and accelerations.','The truck–car interaction forces are equal in magnitude and opposite in direction. If that interaction dominates the net force, the smaller-mass car has the larger acceleration because a = F/m.'),written('Challenge: Reverse which block receives the 10 N push in the worked example. Predict the new contact force.','The combined mass and net external force are unchanged, so acceleration remains 2 m/s². The unpushed 2 kg block now needs contact force 2(2) = 4 N. Equal third-law pairs do not require the contact magnitude to stay the same after changing the external push location.')],
 checklist:['Find a partner by reversing source and receiver.','Explain why partners do not cancel on one FBD.','Use combined and individual systems to find internal forces.']},
'2.4': {
 prerequisites:'Velocity is not acceleration. Net force is the vector sum, not the presence or absence of individual forces.',
 opening:'A puck glides across nearly frictionless ice after the stick loses contact. It keeps moving because no continuing horizontal push is needed to maintain velocity. Forces explain changes of velocity.',
 sections:[section('Inertia and equilibrium','Newton’s first law states that an object maintains its velocity unless a nonzero net external force acts. Inertia is resistance to a change of velocity; mass measures it. Zero net force permits both rest and straight-line motion at constant speed.','A stationary book has several forces with zero vector sum. A gliding puck has approximately zero horizontal net force. “No net force” does not mean “no forces.”'),section('Why everyday motion seems to need pushing','A moving box stops on a rough floor because friction supplies a backward net force. With a steady forward pull that balances friction, it moves at constant velocity. Removing the pull changes the force sum, so it slows.','Do not infer forces from velocity alone. Instead identify interactions and ask whether the velocity changes. An object can move right while accelerating left.'),section('Use an inertial frame','Newton’s laws in their simple form apply in inertial frames, which do not accelerate relative to other inertial frames. A passenger lurching forward during braking is tending to preserve velocity while the vehicle decelerates. The seat belt supplies the real backward force that changes the passenger’s motion.','A frame accelerating with a vehicle requires additional frame-dependent accounting. At this stage, analyse with respect to the approximately inertial ground and identify real interactions.')],
 models:[model('ΣF⃗ = 0 ⇒ a⃗ = 0 ⇒ v⃗ = constant','F: external force (N); a: acceleration (m/s²); v: velocity (m/s).','Translational equilibrium means unchanged velocity, not necessarily zero velocity.','Acceleration measures rate of velocity change. If that rate is zero, both speed and direction stay unchanged.','Use an inertial frame. Circular motion at constant speed is not equilibrium because direction changes.','A straight constant-slope x–t graph and a horizontal v–t graph both represent zero acceleration.')],
 graph:'With zero net force, v–t is horizontal and x–t is straight. The height of v–t gives velocity and need not be zero. A curved path at constant speed still has acceleration, because its velocity direction changes.',
 examples:[example('A 3 kg box moves right at 2 m/s while a 9 N pull balances friction. The pull is removed. Describe the next instant.','Before removal, net horizontal force is zero, so velocity is constant.','Immediately after removal the box still has rightward velocity, but friction gives leftward net force.','Acceleration is leftward; speed decreases over time. Velocity does not jump instantly to zero.'),example('An elevator moves upward at constant speed. Compare upward cable tension and downward weight.','Constant velocity gives zero acceleration.','The vertical sum is T − mg = 0, so T = mg.','Upward velocity by itself is not evidence that tension exceeds weight.')],
 questions:[question('Which observation implies zero net force in an inertial frame?',['Moving right','Moving in a circle at constant speed','Moving along a straight line at constant velocity','Instantaneously having zero speed'],2,'Unchanged velocity implies zero acceleration. At a turning point, speed can be zero with nonzero acceleration.'),question('A puck moves left with negligible horizontal forces. Its later motion is…',['Rest immediately','Left at constant velocity','Right at increasing speed','Left at decreasing speed'],1,'Inertia maintains the existing velocity when net external force is zero.')],
 reasoning:[written('Error analysis: “Acceleration is zero, so there is no gravitational force.” Give a counterexample.','A book at rest on a table has downward gravitational force and upward normal force. Their vector sum is zero. Equilibrium constrains the sum, not each force separately.'),written('Challenge: Describe x–t and v–t for an object starting at x = 3 m and moving at −2 m/s with zero net force.','x(t) = 3 − 2t is a straight descending line with intercept 3 m. v(t) = −2 m/s is a horizontal line below zero. Neither graph indicates a negative speed; the sign specifies direction.')],
 checklist:['Distinguish zero velocity from zero acceleration.','Connect force balance to both motion graphs.','Explain motion after a force is removed.']},
'2.5': {
 prerequisites:'FBDs, signed components, and a = Δv/Δt. Establish forces before substituting into a formula.',
 opening:'Two carts receive the same push. The lighter cart changes velocity faster. Newton’s second law connects the interaction diagram to the acceleration and then to the motion graphs you learned in Unit 1.',
 sections:[section('From interactions to acceleration','The net external force is the cause of acceleration. Acceleration points along the net force, even when velocity points elsewhere. Mass controls how much acceleration a given net force produces. Doubling force at fixed mass doubles acceleration; doubling mass at fixed force halves it.','Apply the law separately along each axis. A direction constrained not to accelerate gives a balance equation. A direction that does accelerate gives a nonzero force sum.'),section('A reliable problem-solving order','Choose the system and an inertial frame. Draw a FBD and axes. Resolve any angled forces. Write symbolic component equations before inserting numbers. Solve for acceleration or unknown forces, then interpret signs and check units.','For connected objects with a taut inextensible string and ideal pulley, their acceleration magnitudes are related by the string constraint. Specify each positive direction consistently. Tension is an unknown force to solve, not automatically equal to weight.'),section('Bridge to motion and experiment','If net force and mass are constant, acceleration is constant and Unit 1 kinematic equations apply. If net force changes, do not use constant-acceleration equations for the entire motion without justification.','To test the law, vary net force while keeping total moving mass fixed and measure acceleration with a motion sensor. Graph acceleration versus net force: slope is 1/M. If mass changes during trials, that simple slope interpretation is invalid.')],
 models:[model('ΣF_x = m a_x; ΣF_y = m a_y','m: inertial mass (kg); component force sums in N; acceleration in m/s².','Divide the component net force by mass to predict that acceleration component.','For a box pulled right with force F against leftward friction f, ΣF_x = F − f = ma_x. It is the difference, not the applied force alone, that accelerates the box.','Inertial frame; fixed mass. Constant acceleration follows only if the net force remains constant.','N/kg = m/s². A negative result means acceleration opposite the chosen positive axis.'),model('T − mg = ma_y ⇒ T = m(g + a_y)','T: tension or upward support force (N); up is positive; g = 9.8 m/s² near Earth.','The support force differs from weight when the object accelerates vertically.','A scale measures the normal support force. Replace T with N for a person on a scale. Upward acceleration requires extra support; downward acceleration requires less.','Only upward support and gravity act vertically in this model. The sign comes from acceleration, not direction of travel.','In free fall a_y = −g, so the support force is zero, although gravity still acts.')],
 graph:'A plot of F_net versus a at fixed mass is a straight line through the origin with slope m. A plot of a versus F_net has slope 1/m. State which quantity is on each axis before interpreting a slope. The v–t slope is the resulting acceleration.',
 examples:[example('A 4 kg box starts from rest. A 20 N horizontal pull acts against 4 N friction for 3 s. Find acceleration and final velocity.','Choose right positive. Net force = 20 − 4 = 16 N.','a = 16/4 = 4 m/s². Forces are constant, so v = v₀ + at applies.','v(3 s) = 12 m/s right. Using 20 N alone would overestimate acceleration.'),example('Masses 3 kg and 2 kg hang on an ideal pulley. Find acceleration and tension.','The 3 kg mass moves down; choose its positive direction down and the 2 kg mass’s direction up.','3g − T = 3a and T − 2g = 2a. Add to eliminate T: g = 5a.','a = 1.96 m/s². T = 2(g + a) = 23.52 N. T lies between the two weights.'),example('A 60 kg person rides an elevator accelerating downward at 2 m/s². Find the scale reading.','Choose upward positive, so a_y = −2 m/s².','N − 60g = 60(−2); N = 60(9.8 − 2) = 468 N.','Weight is still 588 N. The scale reads support force, not the person’s mass or gravitational force.')],
 questions:[question('A 2 kg object has forces 8 N right and 2 N left. Its acceleration is…',['5 m/s² right','3 m/s² right','4 m/s² right','3 m/s² left'],1,'The signed net force is 6 N right. Dividing by 2 kg gives 3 m/s² right.'),question('A graph of acceleration (vertical) versus net force (horizontal) has slope 0.25 kg⁻¹. The mass is…',['0.25 kg','2 kg','4 kg','8 kg'],2,'The slope is 1/m, so m = 1/0.25 = 4 kg.')],
 reasoning:[written('Error analysis: “The elevator moves downward, so the scale reading must be smaller than weight.” Correct the condition.','A smaller scale reading requires downward acceleration. An elevator moving downward while slowing has upward acceleration, giving N > mg. Velocity direction alone is insufficient.'),written('Challenge: Design trials to determine mass using force and acceleration measurements.','Keep the total moving mass fixed, change the known net force, and measure acceleration for multiple trials. Plot F_net vertically against a horizontally; the best-fit slope gives mass in kg. Account for friction or include it in net force, repeat trials, and do not force a nonzero intercept to zero without examining systematic errors.')],
 checklist:['Write component force equations from an FBD.','Solve a connected-system problem using constraints.','Interpret apparent weight and force–acceleration slopes.']},
'2.6': {
 prerequisites:'Newton’s second and third laws. Distinguish mass (kg), gravitational force (N), and gravitational field strength (N/kg).',
 opening:'Gravity holds a satellite in orbit while astronauts inside feel weightless. There is substantial gravitational force at orbital altitude; apparent weightlessness comes from free fall, not the absence of gravity.',
 sections:[section('A universal attractive interaction','Every mass attracts every other mass. For point masses the force acts along the line connecting them. Its magnitude grows with either mass and decreases with the square of centre-to-centre separation. Spherically symmetric bodies can be treated as point masses at their centres when the observation point is outside.','Earth pulls you downward and you pull Earth toward you with an equal force. Their accelerations differ because their masses differ.'),section('From force to gravitational field','The gravitational field g⃗ is force per unit test mass. It describes the source’s influence at a location and exists whether or not a test object is placed there. The field is inward toward an isolated spherical source. Multiplying field strength by test mass gives weight.','Near Earth’s surface, altitude changes are small relative to Earth’s radius, so treating g as constant is a useful approximation. At substantial altitude use r = R_E + h. Altitude alone is not the centre-to-centre distance.'),section('Mass, weight, and free fall','In ideal free fall, m_test g = m_test a; cancelling the test mass gives a = g. This explains equal accelerations for different masses when air resistance is negligible. A scale reads contact force, which can be zero while gravitational force remains nonzero.','An orbiting object is continually falling toward Earth while its tangential motion carries it around. Topic 2.9 will combine this inward gravitational force with the acceleration needed for a circular path.')],
 models:[model('F_g = G m₁m₂/r²; g = GM/r²','G = 6.67 × 10⁻¹¹ N·m²/kg²; masses in kg; r in m; g in N/kg or m/s².','Force compares two masses; field strength depends on the source mass M and location.','Define g = F_g/m_test. Substituting the universal force law cancels m_test and leaves GM/r².','Point masses or outside a spherically symmetric source. For near-surface weight use F_g ≈ mg.','Doubling r gives one quarter the force and field. Doubling only test mass doubles force but leaves field unchanged.')],
 graph:'The g–r graph outside a spherical body follows 1/r², not a straight line. A graph of g versus 1/r² is linear with slope GM. Label r as distance from the source centre and restrict this outside-field formula to r ≥ R.',
 examples:[example('At a distance 2R_E from Earth’s centre, compare gravitational field with its surface value.','Surface value is GM/R_E²; new value is GM/(2R_E)².','The ratio is 1/4, so g ≈ 2.45 m/s² if surface g = 9.8 m/s².','The altitude is R_E, not 2R_E.'),example('A 2 kg mass is released near Earth. Find its weight and acceleration with negligible drag.','Weight is mg = 19.6 N downward.','Newton’s second law gives a = 19.6/2 = 9.8 m/s² downward.','A 5 kg mass has greater weight, 49 N, but the same acceleration because inertia increases in the same proportion.')],
 questions:[question('A satellite’s distance from Earth’s centre triples. Its gravitational force becomes…',['1/3 as large','1/9 as large','3 times as large','9 times as large'],1,'Inverse-square dependence gives 1/(3²) = 1/9 for unchanged masses.'),question('An astronaut in circular orbit feels weightless primarily because…',['Gravity is zero','Mass is zero','The astronaut and spacecraft fall together','Earth no longer attracts small objects'],2,'Both accelerate gravitationally together, so little support force is needed. Gravity supplies orbital acceleration.')],
 reasoning:[written('Error analysis: “Use GM/h² for a satellite at altitude h.” Correct the distance.','The force law uses separation from Earth’s centre: r = R_E + h. Using altitude alone overestimates the field and becomes nonsensical at h = 0.'),written('Challenge: A planet has twice Earth’s mass and twice Earth’s radius. Compare surface field strengths.','g_planet/g_E = (2M_E/M_E)(R_E/(2R_E))² = 1/2. Extra source mass strengthens gravity, but doubling radius reduces it by a factor of four.')],
 checklist:['Use centre-to-centre separation.','Distinguish field strength, force, and apparent weight.','Explain equal free-fall accelerations and inverse-square graphs.']},
'2.7': {
 prerequisites:'Normal force is a constraint force, not always mg. Friction depends on contact and relative motion.',
 opening:'Push gently on a heavy crate and it stays still. Push harder and it still stays still, until a threshold. Static friction adjusts to the required balance; it is not automatically at its maximum.',
 sections:[section('Static friction is a range','Static friction acts when surfaces do not slide relative to one another. Its direction opposes the tendency to slip. It adjusts from zero to a maximum μ_s N. First calculate the friction needed to prevent slipping, then test whether it is within the available range.','Friction need not oppose the object’s velocity relative to the ground. Static friction on a rolling driven tyre can point forward; it opposes slipping at the contact.'),section('Kinetic friction during sliding','Kinetic friction opposes relative sliding between surfaces and is modelled by magnitude μ_k N. In the simple dry-contact model it is approximately independent of contact area and sliding speed. These are approximations; real surfaces can behave differently.','Usually μ_k < μ_s, so maintaining sliding can require less force than initiating it. If an applied force is removed while sliding, friction creates an acceleration opposite velocity until the object stops; do not continue the same sliding-direction formula past that instant.'),section('Use the normal force you actually found','A level surface with no other vertical forces has N = mg. An upward angled pull reduces N; a downward push increases it. On an incline without other perpendicular forces, N = mg cosθ.','For a block at rest on an incline, the required uphill static friction is mg sinθ. Compare this with μ_s mg cosθ to find the no-slip condition tanθ ≤ μ_s.')],
 models:[model('0 ≤ f_s ≤ μ_s N; f_k = μ_k N','f_s and f_k: friction magnitudes (N); N: normal magnitude (N); μ_s, μ_k: dimensionless contact coefficients.','Static friction is whatever value is needed within its bound; kinetic friction uses an approximate fixed magnitude for sliding contact.','At impending slip, f_s reaches μ_s N. Before that, a horizontal force balance can give f_s = F_applied instead.','Dry contact model. Determine whether contact is sticking or sliding and solve perpendicular forces before using N.','A dimensionless coefficient times N yields N. Using μ_s N in every static situation incorrectly predicts motion for a tiny pull.')],
 graph:'Plot friction magnitude versus increasing horizontal applied force for a level crate. While at rest, the graph rises with slope 1 up to μ_s N. After sliding begins, the simple model drops to μ_k N and stays level while N is fixed. This is not a friction-versus-speed graph.',
 examples:[example('A 10 kg crate has μ_s = 0.40 and μ_k = 0.30. It is pulled horizontally with 20 N. Does it move?','N = mg = 98 N. Maximum static friction is 39.2 N.','The friction required for rest is 20 N left, below the maximum. The crate remains still.','Actual friction is 20 N, not 39.2 N.'),example('The same crate is already sliding right and the pull increases to 50 N. Find acceleration.','Use kinetic friction: f_k = 0.30(98) = 29.4 N left.','Net force = 50 − 29.4 = 20.6 N right.','a = 20.6/10 = 2.06 m/s² right.'),example('A block rests on a 20° incline with μ_s = 0.50. Test whether static equilibrium is possible.','Required friction is mg sin20°. Available maximum is 0.50mg cos20°.','Divide by mg cos20°: tan20° ≈ 0.364 < 0.50.','Static friction can supply the required force. Its actual magnitude is mg sin20°, not its maximum.')],
 questions:[question('A level crate has maximum static friction 30 N. An 18 N pull does not move it. Actual static friction is…',['0 N','18 N','30 N','48 N'],1,'Static friction adjusts to balance the pull. The maximum is a bound, not a compulsory value.'),question('An upward angled pull reduces normal force while a crate slides. For fixed μ_k, kinetic friction…',['Increases','Decreases','Stays unchanged','Becomes static automatically'],1,'f_k = μ_k N decreases with N. Whether friction is kinetic depends on relative sliding, not normal force alone.')],
 reasoning:[written('Error analysis: “Friction always points opposite motion.” Refine this claim for static friction.','Kinetic friction opposes relative sliding at contact. Static friction opposes the tendency for relative slipping, so its direction can be the same as the object’s motion relative to the ground, as for a driven tyre.'),written('Challenge: Describe an experiment to estimate μ_s and μ_k for a block on a level surface.','Measure block mass and maximum pull just before sliding, giving μ_s = F_threshold/(mg). Pull at constant speed while sliding and measure the steady pull, giving μ_k = F_pull/(mg). Keep the pull horizontal, repeat trials, and justify N = mg and zero acceleration in the constant-speed trials.')],
 checklist:['Choose static or kinetic friction from contact motion.','Find actual static friction before comparing its bound.','Calculate normal force and justify friction direction.']},
'2.8': {
 prerequisites:'Signed position and restoring-force direction. Define the relaxed length before measuring deformation.',
 opening:'Stretch a spring to the right and it pulls back to the left. Compress it and it pushes toward its relaxed length. The spring force changes with deformation rather than staying constant.',
 sections:[section('Define deformation, not absolute position','The spring’s relaxed length L₀ is its length with no elastic deformation. Let x = L − L₀ along the chosen spring axis. Positive x means stretch; negative x means compression with this convention. The restoring force points opposite x.','The force in Hooke’s law is the force exerted by the spring on the attached object. The object’s force on the spring is the third-law partner and has opposite direction.'),section('Read stiffness physically','The spring constant k measures force needed per unit deformation. A larger k means a stiffer spring, not a larger deformation under the same force. A straight force–deformation relationship is an ideal approximation within the elastic range.','Past the elastic limit, a real spring may deform permanently or stop following a straight-line law. Do not extend the formula indefinitely.'),section('Equilibrium can be away from relaxed length','Hang a mass from a spring. Gravity stretches it until the upward spring force balances weight. With downward displacement positive from relaxed length, net force is mg − kx. Equilibrium occurs at x_eq = mg/k.','Displacement from the new equilibrium is y = x − x_eq. Substitution gives net force −ky. This connection leads to oscillations later; here the goal is force balance and acceleration, not an unexplained oscillation formula.')],
 models:[model('F_s,x = −kx','F_s,x: signed spring-force component (N); k: spring constant (N/m); x: deformation from relaxed length (m).','The minus sign makes the spring restore its relaxed length. Magnitude is k|x|.','For x > 0, F_s,x < 0; for x < 0, F_s,x > 0. The sign follows deformation direction, not whether the object is currently moving.','Hooke’s-law range and a stated reference length. Forces from multiple springs must be added as vectors.','N/m multiplied by m gives N. With x = 0 the elastic force vanishes, but other forces may remain.')],
 graph:'For signed spring force versus signed deformation, the graph passes through the origin with slope −k. A graph of force magnitude versus stretch magnitude has slope +k. Specify which force is measured: the external holding force at equilibrium is +kx, opposite the spring force.',
 examples:[example('A horizontal spring with k = 200 N/m is stretched 0.030 m right. Find its force on a block.','Define positive deformation right from relaxed length.','F_s,x = −200(0.030) = −6 N, meaning 6 N left.','If the block has mass 2 kg and no other horizontal forces, a_x = −3 m/s² at that instant.'),example('A 0.50 kg mass hangs at rest from a 100 N/m spring. Find its extension.','Balance upward spring magnitude kx with downward weight mg.','x = mg/k = (0.50)(9.8)/100 = 0.049 m = 4.9 cm.','This is extension, not the full spring length. Add L₀ to find total length.')],
 questions:[question('A spring is compressed so x = −0.04 m, with k = 50 N/m. Its signed restoring force is…',['−2 N','+2 N','−0.0008 N','+0.0008 N'],1,'F = −kx = −50(−0.04) = +2 N. The spring pushes toward x = 0.'),question('A signed spring-force versus deformation graph has slope −80 N/m. The spring constant is…',['−80 N/m','80 N/m','1/80 N/m','80 N'],1,'The slope is −k. Stiffness k is positive and has units N/m.')],
 reasoning:[written('Error analysis: “The spring pulls left because the block moves right.” Explain the actual condition.','Direction is set by deformation from relaxed length. A stretched spring pulls left even if the block is moving left. Velocity does not determine the restoring-force sign.'),written('Challenge: A hanging mass is displaced 2 cm downward from its equilibrium on a 100 N/m spring. Find net force.','Let y be displacement below equilibrium. Gravity and the equilibrium portion of spring force cancel. Net force = −ky = −100(0.02) = −2 N with down positive, so it is 2 N upward. Do not treat the extra 2 cm as the total extension when computing spring force alone.')],
 checklist:['Define relaxed length and signed deformation.','Interpret the minus sign and force–deformation slope.','Distinguish total spring force from net force near equilibrium.']},
'2.9': {
 prerequisites:'Velocity is a vector; changing its direction causes acceleration. Newton’s second law determines which real interaction supplies that acceleration.',
 opening:'A car turns at constant speed. Its speedometer is steady, but its velocity changes because direction changes. An inward net force bends the path; it does not necessarily increase the speed.',
 sections:[section('Velocity tangent, acceleration inward','For uniform circular motion, velocity is tangent to the path and acceleration is toward the centre. In a short time the velocity vector rotates. The inward change of velocity divided by elapsed time gives acceleration.','Geometrically, Δv/v ≈ Δs/r for a small arc. Since Δs/Δt = v, acceleration magnitude approaches v²/r. This explains both the squared speed dependence and why a tighter curve requires more acceleration.'),section('Centripetal names a direction of the net force','Centripetal means centre-seeking. It is not a new interaction to add to a FBD. Gravity can provide it for an orbit; tension for a ball on a string; friction for a car on a level turn; a combination of forces can provide it too.','Write the real forces along a radial axis pointing inward. Their signed sum must equal mv²/r. If the motion is nonuniform, a tangential force component changes speed as well; radial acceleration still equals v²/r instantaneously.'),section('Vertical circles and loss of contact','At the top of a vertical circle, inward is downward. Gravity and inward contact force can both contribute. At the bottom, inward is upward, so inward support minus weight gives mv²/r. The required support therefore changes around the circle.','Contact normal force cannot pull the object toward a surface. If solving an assumed-contact equation gives N < 0, the assumption fails and contact is lost. For a mass on a taut string at the top, the minimum taut-string speed occurs at T = 0, giving v_min = √(gr).'),section('Circular orbits and the period','In a circular orbit around a spherical source, gravity is the inward net force. Setting GMm/r² = mv²/r cancels orbiting mass and gives v = √(GM/r). A larger orbital radius gives a lower speed and a longer period.','Period T is time for one revolution; frequency f is revolutions per second. One circumference 2πr is travelled in time T, so v = 2πr/T and f = 1/T.')],
 models:[model('a_r = v²/r; ΣF_inward = mv²/r','v: instantaneous speed (m/s); r: path radius (m); inward force sum in N.','Greater speed makes the velocity vector change direction faster; smaller radius requires a sharper turn.','The similar triangles of short arc displacement and velocity change give Δv/v ≈ Δs/r. Divide by Δt and use Δs/Δt = v.','Radial component for circular motion. Acceleration is entirely radial only when speed is constant.','Doubling v quadruples required inward net force. Units v²/r are m/s².'),model('v = 2πr/T; f = 1/T','T: period (s); f: frequency (Hz = s⁻¹); r: radius (m).','Speed is distance around one circle divided by the time per revolution.','For uniform motion one revolution covers circumference 2πr. Divide by T.','Constant speed for this full-revolution average to equal instantaneous speed.','Period increases if speed decreases at fixed radius; T and f are reciprocal.')],
 graph:'A spatial circle is not an x–t graph. At each point draw a tangent velocity and inward radial acceleration. At fixed r, a_r versus v is a parabola; a_r versus v² is linear with slope 1/r. For uniform motion a speed–time graph is horizontal while acceleration is still nonzero.',
 examples:[example('A 1000 kg car turns at 10 m/s on a level circle of radius 50 m. Find required friction.','Draw weight down, normal up, and static friction inward. Vertical forces balance.','Radial net force = mv²/r = 1000(100)/50 = 2000 N inward.','This must be within μ_s N. With N = 9800 N, the needed coefficient is at least 2000/9800 ≈ 0.204.'),example('A 0.20 kg ball moves at 4 m/s at the bottom of a vertical circle of radius 0.80 m. Find string tension.','Choose inward (up) positive at the bottom: T − mg = mv²/r.','T = 0.20(16)/0.80 + 0.20(9.8) = 5.96 N.','At the top, radial signs differ. Never copy the bottom equation without redrawing the directions.'),example('A satellite’s circular orbit radius becomes four times as large. Compare speed and period.','v ∝ 1/√r from gravity = mv²/r, so new speed is one half.','T = 2πr/v, so new period factor is 4/(1/2) = 8.','The satellite mass cancels; it does not set this ideal orbital speed.')],
 questions:[question('Doubling speed at unchanged radius requires inward net force…',['Twice as large','Four times as large','One half as large','Unchanged'],1,'The required net force is proportional to v², so it increases by 2² = 4.'),question('A ball’s string breaks while it moves uniformly in a horizontal circle. Immediately after release, its horizontal velocity is…',['Radially inward','Radially outward','Tangent to the former path','Zero'],2,'Velocity was tangent at release. Removing the inward force does not instantaneously erase or rotate that velocity.')],
 reasoning:[written('Error analysis: “Draw gravity down, tension inward, and centripetal force inward.” Correct the diagram.','Centripetal force is the inward resultant of real interactions, not an extra arrow. Keep gravity and tension as applicable, resolve their radial components, and set their inward sum equal to mv²/r.'),written('Challenge: Derive the maximum speed for a level circular turn with coefficient μ_s.','Vertical balance gives N = mg. At the no-slip limit, μ_s mg = mv²/r. Cancelling m gives v_max = √(μ_s gr). This assumes a level turn, no other horizontal forces, and static contact; sliding invalidates the static-friction limit.')],
 checklist:['Distinguish tangent velocity from inward acceleration.','Use actual forces in the radial equation.','Explain speed/radius scaling, vertical-circle signs, and orbital motion.']},
'9.1': {
 prerequisites:'Kinetic energy K = ½mv², momentum p = mv, and force as momentum change per time. A gas consists of many particles moving in different directions; average vector velocity can be zero while average speed is positive.',
 opening:'A sealed tyre exerts pressure even when it is not moving. Its molecules keep colliding with the walls. Heating changes their random motion, which changes the average force on the tyre. Thermodynamics connects these microscopic events to measurable pressure and temperature.',
 sections:[section('Pressure begins with momentum transfer','An atom approaching a wall with perpendicular velocity v_x and leaving elastically with −v_x changes its perpendicular momentum by −2mv_x. The wall receives an equal opposite impulse. Many collisions per second create a nearly steady average force. Pressure is that perpendicular force divided by surface area.','Pressure is present throughout the gas, not just at its walls: a small imaginary surface placed inside the gas also experiences momentum transfer. Pressure is a scalar; the force it produces on a surface is perpendicular to that surface.'),section('Temperature is not total energy','Temperature describes the average random translational kinetic energy per particle for a classical ideal gas. Two samples at the same temperature can contain very different total energies because one contains more particles or different additional molecular degrees of freedom.','A monatomic gas stores internal energy in the translation of its atoms. A molecular gas may also store energy in rotations or vibrations. Keep the monatomic assumption explicit when using U = (3/2)nRT.'),section('Why kelvin is essential','Kelvin temperature is measured from absolute zero: T(K) = T(°C) + 273.15. A difference of 1 K has the same size as a difference of 1 °C, but their zero points differ. A ratio like “twice the temperature” in gas equations must use kelvin.','The classical model extrapolates toward zero average translational kinetic energy at 0 K. Real quantum systems do not justify claiming that every possible microscopic motion vanishes there.'),section('A distribution of speeds, not one speed','At a given temperature atoms have a range of speeds. A Maxwell–Boltzmann speed distribution plots how many particles fall within each speed interval. The area represents the particle count, or 1 if normalized as a probability density. The peak is the most probable speed, not the mean or the root-mean-square speed.','For the same gas at higher temperature, the curve broadens, its peak moves toward greater speed, and its peak height decreases while total area stays unchanged for unchanged particle count. For different molecular masses at equal temperature, lighter particles have larger characteristic speeds but the same average translational kinetic energy.'),section('What root-mean-square speed means','First square every speed, average those squares, then take the square root: v_rms = √⟨v²⟩. This speed is useful because kinetic energy depends on v². It is not the speed of every atom and differs from the peak of a speed distribution.','Since average translational kinetic energy is ½m⟨v²⟩, combining it with (3/2)k_B T gives v_rms = √(3k_B T/m). Squaring matters: doubling v_rms requires four times the absolute temperature for the same gas.')],
 models:[model('P = F_perpendicular/A','P: pressure (Pa = N/m²); F_perpendicular: total perpendicular force (N); A: surface area (m²).','Pressure describes how concentrated the normal force is over a surface.','For uniform pressure, rearrange to F = PA. The same pressure acting on twice the area gives twice the total force.','Uniform pressure over the specified surface, or interpret P as an area average. Use the perpendicular component.','Pa·m² = N. Pressure is not energy and does not have a vector direction.'),model('K_avg = (3/2)k_B T; v_rms = √(3k_B T/m)','K_avg: average translational kinetic energy per particle (J); k_B = 1.38 × 10⁻²³ J/K; m: mass of one particle (kg); T in K.','Temperature sets mean particle energy; particle mass then sets the typical speed needed for that energy.','Set ½m⟨v²⟩ = (3/2)k_B T and solve for √⟨v²⟩. The three comes from the three independent translational directions.','Classical ideal gas in three dimensions. Use one particle’s mass with k_B, not total sample mass.','J/kg = m²/s² under the square root. Doubling T multiplies v_rms by √2.'),model('U = N K_avg = (3/2)Nk_B T = (3/2)nRT','N: particle count; n: amount in mol; U: internal energy (J); R = 8.314 J/(mol·K).','For a monatomic ideal gas, sum the average translational energy over all particles.','N = nN_A and R = N_A k_B make the particle and mole forms equivalent.','Monatomic ideal gas with negligible interaction potential energy. It is not a universal formula for liquids, solids, or all molecular gases.','At fixed T, doubling particle count doubles U while K_avg stays unchanged.')],
 graph:'Read speed horizontally and particle count per unit speed vertically. Count particles in a speed interval using area, not curve height alone. In the normalized graph below, both full curves have unit area; the visible high-speed tails are very small, not mathematically zero.',
 examples:[example('The rms speed of one gas changes from 400 to 800 m/s. Initially it is at 200 K. Find final temperature.','Use v_rms² = 3k_B T/m. For unchanged gas, v₂²/v₁² = T₂/T₁.','T₂ = 200(800/400)² = 800 K.','A speed factor of 2 means a temperature factor of 4, not 2.'),example('Helium particles have one tenth the mass of another gas’s particles. Both gases have the same temperature. Compare rms speeds and average translational energies.','At fixed T, v_rms ∝ 1/√m. Thus helium rms speed is √10 times larger.','K_avg = (3/2)k_B T is identical for both.','Different speeds compensate for different masses; equal temperature does not mean equal speed.'),example('A gas exerts 300 N over 0.025 m². Find pressure and interpret a doubled area.','P = 300/0.025 = 12,000 Pa = 12 kPa.','At the same uniform pressure over 0.050 m², F = PA = 600 N.','Doubling area doubles total force, not pressure.')],
 questions:[question('Two samples of the same ideal gas contain equal particle counts, at 300 K and 600 K. What is unchanged between their normalized speed distributions?',['Peak speed','Peak height','Total area','Distribution width'],2,'Normalization represents the same total probability. Higher temperature changes the shape, spreading particles over a wider range of speeds.'),question('At unchanged particle mass, T increases by a factor of 9. The rms speed increases by…',['3','9','81','1/3'],0,'v_rms ∝ √T, so the factor is √9 = 3. Average translational energy increases by 9.'),question('Two monatomic ideal-gas samples have equal T but one has twice as many particles. That sample has…',['Twice the average particle energy','Twice the internal energy','Twice the rms speed','Zero pressure'],1,'U = N K_avg, while K_avg and rms speed are fixed by temperature and particle mass.')],
 reasoning:[written('Error analysis: “The peak of a speed distribution is the speed of all particles.” Explain what the curve represents.','A gas has a distribution of speeds. The peak identifies the most probable speed interval. Particles also occupy other intervals. Total particle count comes from area under the curve, while rms speed comes from the mean squared speed.'),written('AP reasoning: A sealed rigid container warms without gas escaping. Explain pressure increase microscopically and macroscopically.','Microscopically faster random motion produces greater perpendicular momentum transfer per time to the walls. Macroscopically n and V are fixed, so the ideal gas relation gives P ∝ T. State temperatures in kelvin and distinguish this from a change in particle count.')],
 checklist:['Explain wall pressure using particle momentum transfer.','Distinguish temperature, mean particle energy, and total internal energy.','Interpret speed-distribution area and rms-speed scaling.']},
'9.2': {
 prerequisites:'Pressure and kelvin temperature from 9.1. A mole counts particles: N = nN_A, where N_A = 6.022 × 10²³ mol⁻¹. Distinguish n (moles) from N (particles).',
 opening:'A gas can be compressed, heated, or allowed to expand. PV = nRT connects its equilibrium states, but its meaning is more useful than a substitution recipe: pressure reflects particle energy concentrated into a given volume.',
 sections:[section('State the ideal-gas assumptions','An ideal gas has particles whose own volume is negligible compared with container volume. Their motion is random, collisions are elastic, and interactions between particles are negligible except during collisions. This often approximates dilute gases away from condensation.','A state is described by quantities such as pressure P, volume V, amount n, and temperature T after the gas is sufficiently close to equilibrium. During a rapid nonequilibrium process, a single pressure or temperature may not describe the whole sample.'),section('Understand PV = nRT from microscopic energy','Kinetic theory gives PV = (2/3)N K_avg. Substitute K_avg = (3/2)k_B T: the factors 2/3 and 3/2 cancel, leaving PV = Nk_B T. Because N = nN_A and R = N_A k_B, this becomes PV = nRT.','P = nRT/V says pressure increases when the sample contains more particles or greater average energy, and decreases when the same particles occupy more volume. PV has units of energy, but it is not itself generally the heat supplied or the work done in a process.'),section('Choose consistent units and pressure','Use P in Pa, V in m³, n in mol, T in K, and R = 8.314 J/(mol·K). Convert 1 L to 0.001 m³ and 1 kPa to 1000 Pa. Absolute pressure is measured relative to vacuum. Gauge pressure measures excess above atmospheric pressure, so P_absolute = P_gauge + P_atmosphere.','For particle count use Nk_B T instead of nRT. A sample’s total mass is not its mole count: if molar mass M is given in kg/mol, n = mass/M.'),section('Identify what is held fixed','A sealed container fixes n, not automatically P or V. A rigid container fixes V. Slow contact with a large thermal reservoir can maintain approximately constant T. A freely moving loaded piston can hold pressure approximately constant. A flexible balloon is not necessarily constant-volume or constant-pressure; justify the constraint.','At fixed n, P₁V₁/T₁ = P₂V₂/T₂. For constant T this reduces to P₁V₁ = P₂V₂; for constant V, P₁/T₁ = P₂/T₂; for constant P, V₁/T₁ = V₂/T₂.'),section('Translate between three graph types','At fixed n and T, P versus V is a hyperbola: P ∝ 1/V. At fixed n and V, P versus T in kelvin is a straight line through the ideal-model origin, with slope nR/V. At fixed n and P, V versus T in kelvin is a straight line with slope nR/P.','Plotting P versus Celsius temperature gives an intercept at −273.15 °C when extrapolated to zero pressure. This is a model extrapolation; a real gas may condense before that point. Linearizing P against 1/V at fixed T gives slope nRT. Always state which variables stayed fixed.'),section('State equations do not choose a process','Two endpoints can satisfy the same ideal gas law but be joined by different P–V paths. Heat and work depend on the path, which requires additional process information. Topic 9.4 will connect a path to energy conservation.','A higher-temperature isotherm lies above a lower-temperature one at the same V and n. Compare states using PV to compare temperatures, not pressure alone when volumes differ.')],
 models:[model('PV = nRT = Nk_B T','P: absolute pressure (Pa); V: gas volume (m³); n: amount (mol); N: particle count; T: absolute temperature (K).','It relates the macroscopic state to the number and average translational energy of particles.','PV = (2/3)N K_avg and K_avg = (3/2)k_B T give PV = Nk_B T. Replacing N k_B with nR gives the mole form.','Classical ideal gas near equilibrium. Choose the constants for the counting convention. It supplies no path or heat-transfer information.','Pa·m³ = N·m = J; mol·[J/(mol·K)]·K = J. Both sides have energy units.'),model('P₂/P₁ = (n₂/n₁)(T₂/T₁)(V₁/V₂)','Each ratio is dimensionless; pressures absolute and temperatures in K.','State changes combine amount, energy per particle, and concentration effects.','Rearrange each state as P = nRT/V and divide; R cancels.','Fixed n is needed only if you cancel the mole-count ratio. Do not cancel V for a movable container.','Doubling T and doubling V at unchanged n leaves P unchanged.')],
 graph:'The quantitative explorer uses P(kPa) = 0.20 × 8.314 × T(K)/V(L). The litre and kilopascal conversions cancel in this form. At 300 K, V = 2, 5, and 10 L give about 249, 99.8, and 49.9 kPa. A curve is an isotherm; moving the temperature slider selects a different curve, not a specified thermodynamic path.',
 examples:[example('Find pressure of 0.20 mol at 300 K in 5.0 L.','Convert 5.0 L = 0.0050 m³. Choose P = nRT/V.','P = (0.20)(8.314)(300)/0.0050 = 99,768 Pa ≈ 99.8 kPa absolute.','Check: PV ≈ 499 J equals nRT. A result of 99.8 Pa would reveal a conversion error.'),example('A sealed piston sample expands from 2.0 to 6.0 L while warming from 300 to 450 K. Initially P = 180 kPa. Find final pressure.','Amount is fixed; volume and temperature both change.','P₂ = 180(450/300)(2/6) = 90 kPa.','Heating tends to raise pressure by 1.5, but expansion lowers it by 3; combined pressure halves.'),example('A rigid container’s gauge pressure is 100 kPa at 300 K. Atmospheric pressure is 100 kPa. Find gauge pressure at 450 K.','Initial absolute pressure is 200 kPa. At fixed n,V, absolute pressure scales with kelvin temperature.','P₂,absolute = 200(450/300) = 300 kPa.','Final gauge pressure is 300 − 100 = 200 kPa. Scaling gauge pressure directly would be wrong.')],
 questions:[question('A sealed ideal gas doubles both absolute temperature and volume. Its pressure…',['Doubles','Halves','Stays the same','Quadruples'],2,'P ∝ T/V for fixed n. The two factors cancel.'),question('At fixed gas amount and temperature, which graph is linear?',['P versus V','P versus 1/V','P versus V²','T versus P with varying V'],1,'P = (nRT)(1/V), so slope is nRT when 1/V is horizontal.'),question('States A and B have P_B = 2P_A and V_B = V_A/4 for unchanged amount. T_B/T_A equals…',['8','2','1/2','1/4'],2,'T ∝ PV at fixed n. The product factor is 2 × 1/4 = 1/2.')],
 reasoning:[written('Error analysis: “A sealed balloon is heated, so P must rise in proportion to T.” Identify the missing constraint.','Sealed means n is fixed, but the balloon can expand. P is proportional to T only when V also stays fixed. The gas law gives P ∝ T/V, so both changes must be considered.'),written('Experimental design: Determine the amount of gas from a pressure–temperature graph in a rigid container.','Measure absolute pressure at multiple kelvin temperatures after thermal equilibrium, with known fixed volume and no leaks. Plot P vertically versus T horizontally. The slope s = nR/V gives n = sV/R. Repeat measurements, account for gauge-to-absolute conversion, and avoid temperatures where condensation invalidates the ideal-gas model.')],
 checklist:['Explain each symbol and the physical content of PV = nRT.','Choose real constraints before simplifying a ratio.','Read and linearize P–V and P–T graphs with units.']},
'9.3': {
 prerequisites:'Temperature measures average particle energy, while internal energy is a system total. Define a system boundary before tracing energy transfers.',
 opening:'A small hot nail can cool when placed in a large cooler bath, even if the bath initially stores more total internal energy. The temperature difference determines the direction of spontaneous heat transfer.',
 sections:[section('Heat is energy in transit','Heat Q is energy crossing a system boundary because of a temperature difference. Internal energy U is energy stored in microscopic motions and interactions. An object has internal energy; saying it “contains heat” obscures the distinction between storage and transfer.','Choose Q positive when heat enters the chosen system and negative when it leaves. Reversing which body is the system reverses the sign of the same transfer.'),section('Conduction: microscopic transfer without bulk flow','In conduction, interactions among neighbouring particles transfer energy without the material as a whole moving from hot region to cold region. In metals, mobile electrons can also transport energy. A metal spoon in hot water conducts energy along its length.','Energy flows net from hotter to colder regions. Individual microscopic interactions can transfer either way; the statistically favoured net flow is set by the temperature difference.'),section('Convection and radiation','Convection transports energy through bulk motion of a fluid, such as warm air rising and cool air replacing it. It requires a material fluid. Radiation transfers energy through electromagnetic waves and can cross vacuum. All objects at nonzero temperature emit radiation; the net exchange depends on their temperatures and surfaces.','A vacuum suppresses conduction and convection across the gap but does not eliminate radiation. Real cooling can involve more than one mechanism at once.'),section('Thermal equilibrium and the zeroth law','Two bodies in thermal contact reach thermal equilibrium when there is no net thermal transfer between them, corresponding to equal temperature. Particles still move and exchange energy microscopically; equilibrium does not mean motion ceases.','If A and B are each in thermal equilibrium with a thermometer C, they share the same temperature and would be in thermal equilibrium with each other. This is the basis of using temperature as a reproducible measurement.'),section('Conservation for an isolated combination','When the combined system is insulated from its surroundings and work is negligible, energy lost by one part equals energy gained by the others. Include the container if its thermal response is significant.','Equal final temperature does not mean equal final internal energy. Mass, material, and phase determine how much energy is stored. Topic 9.5 will quantify how different heat capacities change the final equilibrium temperature.')],
 models:[model('Q_hot + Q_cold + Q_container = 0','Each Q is signed heat into the specified component in J.','Inside an isolated combined system, internal exchanges balance.','Draw the combined boundary. Energy lost by the hot object crosses into the cold body and possibly the container; summing the signed transfers gives zero.','Negligible external heat leakage, no significant mechanical work, and all relevant components included.','The hot body has Q < 0 and the cold body Q > 0. Equal signs for both would violate the chosen conservation model.')],
 graph:'On a T–t graph of two isolated bodies approaching equilibrium, the hot curve decreases and the cold curve increases toward the same final temperature. Their temperature changes need not be equal. Curve slopes show rates of temperature change, not heat-transfer rate without additional heat-capacity information.',
 examples:[example('A hot object loses 500 J in an insulated mixture. The container gains 80 J. Find heat gained by the cold liquid.','Choose the mixture plus container as the isolated combined system.','−500 + 80 + Q_liquid = 0. Thus Q_liquid = +420 J.','Ignoring the container would overestimate liquid energy gain.'),example('Why can sunlight warm an object inside a vacuum chamber?','Conduction and convection across vacuum are absent in the idealized gap.','Electromagnetic radiation travels across vacuum and transfers energy when absorbed.','The object also emits radiation; its temperature rises when net energy input is positive.')],
 questions:[question('Two objects are in thermal equilibrium. They necessarily have the same…',['Mass','Internal energy','Temperature','Specific heat'],2,'Equal temperature means no net thermal exchange in contact. Equal energy is not required.'),question('Which transfer mechanism can cross vacuum?',['Conduction through gas','Convection','Radiation','Fluid circulation'],2,'Electromagnetic radiation requires no material medium.'),question('A hot metal block warms cold water in an insulated cup. Which statement is correct?',['Heat flows because metal has more total energy','The temperature difference determines net transfer direction','Particles stop moving at equilibrium','The water and metal must gain equal energy'],1,'Net thermal transfer is driven by temperature difference. One component loses energy while the other gains it.')],
 reasoning:[written('Error analysis: “A large cold bath warms a small hot nail because it has more total internal energy.” Correct the prediction.','Heat flows spontaneously from the higher-temperature nail to the lower-temperature bath. Total energy alone does not set the direction. The nail loses energy and the bath gains it until they reach the same temperature.'),written('Experimental reasoning: Why must a thermometer be left in contact before recording temperature?','It initially exchanges energy with the sample. Its reading represents the sample temperature only after it approaches thermal equilibrium. A thermometer with significant heat capacity can disturb a small sample, so use a suitably small probe and allow sufficient time.')],
 checklist:['Distinguish stored internal energy from transferred heat.','Identify conduction, convection, and radiation.','Use a combined-system energy balance and explain equilibrium.']},
'9.4': {
 prerequisites:'PV = nRT connects equilibrium states. Work transfers energy mechanically; heat transfers it thermally. State a work sign convention before balancing energy.',
 opening:'Heat a gas under a movable piston. Some energy can increase the random motion of particles, while some leaves as the gas pushes the piston outward. The first law keeps track of both destinations.',
 sections:[section('Choose the gas and track its boundary','Let the gas be the system. Q is positive for heat entering. W_by is positive when the gas does work on its surroundings. Conservation says its internal-energy increase is incoming heat minus outgoing work: ΔU = Q − W_by.','College Board’s work-on form uses W_on = −W_by, giving ΔU = Q + W_on. Compression usually has positive work on the gas; expansion usually has positive work by it. Both conventions are correct when labelled and used consistently.'),section('Why P–V area represents work','For a piston of area A moving a short distance Δx against external pressure P_ext, the gas pushes with force P_ext A and displaces volume ΔV = AΔx. Work done by the gas is force times displacement: W_by = P_ext AΔx = P_ext ΔV.','For a slow quasi-static path, gas pressure nearly matches external pressure, so the area under P(V) gives work by the gas. Constant pressure gives a rectangle; a straight sloping path gives a trapezoid. A rapid nonequilibrium expansion generally requires external pressure information rather than an assumed gas-pressure path.'),section('Internal energy depends on endpoints; heat and work depend on path','For a monatomic ideal gas, U = (3/2)nRT = (3/2)PV. Thus ΔU follows the starting and ending temperatures, or their PV products for fixed amount. Two paths between the same equilibrium states have the same ΔU but can have different work. Heat must differ accordingly.','Use the ideal gas law to compare endpoint temperatures, calculate work from the actual path, then apply the first law. An equation of state alone does not specify heat.'),section('Four process types with different constraints','Isochoric means fixed volume: ΔV = 0, so boundary work is zero and Q = ΔU. Isobaric means fixed pressure: W_by = PΔV. Isothermal means constant temperature: an ideal gas has ΔU = 0, so Q = W_by. Adiabatic means negligible heat transfer: Q = 0, so ΔU = −W_by.','Adiabatic expansion that performs positive work cools an ideal gas. Free expansion into vacuum has W_by = 0 and Q = 0 in an insulated container; ideal-gas internal energy and temperature then stay unchanged. Do not confuse adiabatic with isothermal.'),section('Cycles and the loop area','A cycle returns to its initial state, so total ΔU = 0 and Q_net = W_by,net. A clockwise P–V cycle has higher pressure during expansion than compression and therefore positive net work by the gas. The enclosed area measures that net work.','For a counterclockwise cycle, net work by the gas is negative: the surroundings supply net work. Heat transfers on individual legs still require the first law; positive work on one leg does not guarantee positive heat on every leg.'),section('Work is not the product PV for any process','PV describes a state and has energy units. Work depends on how volume changes along a path. A fixed-volume gas can have large PV yet do zero boundary work. A constant-pressure process uses PΔV, not its final PV.','For curved paths, use a provided area, count graph squares, or apply an appropriate stated relationship. Calculus is not needed to interpret graph area in this algebra-based course.')],
 models:[model('ΔU = Q − W_by = Q + W_on','ΔU, Q, W in J. Heat into the gas positive; work by gas outward positive; W_on = −W_by.','Stored energy changes by net energy transferred into the system.','Choose a boundary and label energy arrows before inserting signs. Rearranging gives Q = ΔU + W_by.','Include the stated heat and work channels; do not treat internal energy as heat or use mixed work conventions.','If Q = 0 and compression does 50 J on the gas, ΔU = +50 J.'),model('W_by = PΔV (constant pressure); ΔU = (3/2)nRΔT (monatomic ideal gas)','P in Pa; ΔV in m³; n in mol; ΔT in K; results in J.','The first relation is a rectangular path area; the second is an endpoint temperature change.','Force P A times piston displacement Δx gives PΔV. Subtract U₁ from U₂ = (3/2)nRT for the energy relation.','Constant pressure for the work formula; fixed-amount monatomic ideal gas for the energy formula.','Expansion makes ΔV positive. Cooling makes ΔT negative. Pa·m³ and nRΔT both have units J.')],
 graph:'The process explorer below shows a stated constant-pressure expansion from 2 to 5 L at 100 kPa. Its shaded work is 100 kPa × 3 L = 300 J. The vertical axis must start at zero when interpreting full area under a path. Reversing the arrow changes work sign without changing the rectangular area magnitude.',
 examples:[example('A monatomic ideal gas expands at 100 kPa from 2.0 to 5.0 L. Find work, internal-energy change, and heat.','Convert ΔV = 0.0030 m³. W_by = 100,000(0.0030) = 300 J.','At fixed pressure, Δ(PV) = 300 J. ΔU = (3/2)Δ(PV) = 450 J.','Q = ΔU + W_by = 750 J. The heat supplies both increased internal energy and outward work.'),example('Two paths connect A = (2 L, 100 kPa) to B = (4 L, 200 kPa). Path I first raises P at fixed V, then expands at 200 kPa. Path II first expands at 100 kPa, then raises P at fixed V. Compare work and heat.','Both paths have Δ(PV) = 800 − 200 = 600 J, so ΔU = 900 J for a monatomic ideal gas.','Path I work = 200 kPa × 2 L = 400 J. Path II work = 100 kPa × 2 L = 200 J. Vertical legs do zero work.','Q_I = 1300 J and Q_II = 1100 J. Endpoints fix ΔU; paths fix W and hence Q.'),example('A rectangular clockwise cycle has pressures 100 and 300 kPa and volumes 2 and 4 L. Find net work and net heat.','Enclosed area = (300 − 100)(4 − 2) = 400 kPa·L = 400 J.','Clockwise gives W_by,net = +400 J.','Returning to the initial state gives ΔU_net = 0, so Q_net = +400 J.')],
 questions:[question('An insulated gas is compressed with 80 J of work done on it. Its internal-energy change is…',['−80 J','0 J','+80 J','Cannot be determined from energy conservation'],2,'Q = 0 and W_on = +80 J, so ΔU = +80 J.'),question('An ideal gas expands isothermally and does 120 J of work. Heat entering it equals…',['0 J','−120 J','+120 J','+240 J'],2,'For an ideal gas, constant temperature gives ΔU = 0. Q = W_by = +120 J.'),question('Two paths connect the same initial and final equilibrium states. Which quantity must be equal?',['Heat transfer','Work','Internal-energy change','Area under the path'],2,'Internal energy is a state function. Heat and work depend on the path.')],
 reasoning:[written('Error analysis: “Heat absorbed always raises temperature.” Give two thermodynamic counterexamples.','During an isothermal ideal-gas expansion, heat can entirely balance work by the gas while ΔU and T stay unchanged. During a phase change, heat can alter microscopic configuration without raising temperature. Specify the process before inferring a temperature change.'),written('Challenge: An ideal gas completes a counterclockwise P–V cycle with enclosed area 250 J. State signs of net work by, work on, and net heat.','W_by,net = −250 J, W_on,net = +250 J, and ΔU_net = 0. Thus Q_net = −250 J: the system releases net heat while receiving net work.')],
 checklist:['Use and translate work-by and work-on conventions.','Calculate signed P–V area from a specified path.','Connect endpoint temperature, ΔU, path-dependent work, and heat.']},
'9.5': {
 prerequisites:'Signed heat and isolated-system energy balance. Temperature differences can use kelvin or Celsius, but absolute-temperature ratios require kelvin.',
 opening:'Equal heaters warm equal masses of water and metal at different rates. Some materials need more energy per degree. Melting can take energy without any temperature increase. A separate property determines how quickly energy conducts through a material.',
 sections:[section('Specific heat versus heat capacity','Specific heat c is energy needed per kilogram per kelvin: J/(kg·K). Heat capacity C = mc is energy needed for the whole object per kelvin. For approximately constant c and no phase change, Q = mcΔT.','A negative ΔT makes Q negative for cooling. This simple thermal model assumes heat primarily changes internal energy and other work is negligible or incorporated in the appropriate measured specific heat.'),section('Explain slopes on heating graphs','A graph of T against energy added Q has slope 1/(mc) within a phase. A smaller heat capacity produces a steeper rise. A graph of Q against ΔT instead has slope mc. Under constant heating power P and negligible losses, Q = Pt and dT/dt = P/(mc).','Do not interchange energy and time axes unless heater power is constant and known. The same temperature rise can require different times under different power inputs.'),section('Phase changes require a separate energy step','Latent heat L is energy per kilogram for a transition at its transition temperature: Q = mL for melting or vaporization, and Q = −mL for freezing or condensation. During a plateau at fixed pressure, the added energy changes phase rather than temperature.','For heating ice below 0 °C to liquid above 0 °C, calculate warming ice, melting, then warming water separately. Do not use one c across phases. If available energy is insufficient for full melting, the final state may be a mixture at the transition temperature.'),section('Derive equilibrium temperature','For two bodies exchanging energy in an insulated container, m₁c₁(T_f − T₁) + m₂c₂(T_f − T₂) = 0. Rearranging gives T_f = (C₁T₁ + C₂T₂)/(C₁ + C₂), where C_i = m_i c_i.','The final temperature lies between the initial temperatures if no phase change or other energy source is present. It lies closer to the initial temperature of the body with greater heat capacity. Include container heat capacity if significant.'),section('Thermal conductivity describes rate, not storage','For a uniform slab with maintained face temperatures, thermal-transfer power is κA(T_hot − T_cold)/d. Larger conductivity or area means more parallel paths for energy flow. Greater thickness means a longer path and smaller rate.','Specific heat describes energy storage per temperature change. Thermal conductivity describes transport rate. They have different units and neither can replace the other. Steady conduction assumes approximately fixed face temperatures and negligible side losses.'),section('Build an experiment with a usable graph','To measure specific heat, deliver measured energy to a known mass and graph Q versus ΔT after equilibration. The slope gives mc. To compare conductivities, hold slab area, thickness, and face temperature difference fixed and compare steady power.','Insulation, temperature-sensor placement, heater calibration, and container heating matter. A heat-loss bias can make a naïve Q/ΔT measurement overestimate the material’s heat capacity.')],
 models:[model('Q = mcΔT; Q_phase = ±mL','m: mass (kg); c: specific heat [J/(kg·K)]; ΔT: temperature change; L: latent heat (J/kg).','Within a phase heat changes temperature; during a transition it changes phase at nearly fixed temperature.','Specific heat is energy per mass per degree, so multiply by both. Latent heat is energy per mass, so multiply only by mass. Add stages rather than mixing formulas.','Approximately constant c within each stage; phase transition at stated pressure. Latent-heat signs follow the energy direction.','kg × J/(kg·K) × K = J. A plateau does not imply zero energy transfer.'),model('P_thermal = κA(T_hot − T_cold)/d','κ: conductivity [W/(m·K)]; A: slab cross-sectional area (m²); d: thickness (m); P_thermal: transfer rate (W).','A temperature gradient drives conduction; a longer slab reduces the gradient at fixed face temperatures.','Write gradient magnitude ΔT/d, then multiply by κA. Transfer over time Δt is Q = P_thermal Δt if power stays constant.','Steady uniform slab; maintained face temperatures; negligible edge losses; approximately constant κ.','W/(m·K) × m² × K/m = W. Doubling thickness halves the rate, not the eventual stored energy.')],
 graph:'The heating-curve explorer uses 0.10 kg of ice starting at −20 °C. It uses c_ice = 2100 J/(kg·K), L_f = 334,000 J/kg, and c_water = 4180 J/(kg·K). Warming ice requires 4.2 kJ, melting requires 33.4 kJ, and only then does liquid temperature rise. The plateau width is energy, not elapsed time.',
 examples:[example('Mix 0.20 kg of water at 80 °C with 0.30 kg at 20 °C in an ideal insulated cup. Find equilibrium temperature.','Same material c cancels: 0.20(T_f − 80) + 0.30(T_f − 20) = 0.','0.50T_f = 22, so T_f = 44 °C.','The hot portion loses heat while the cold gains it. The answer is nearer 20 °C because the cold portion has greater heat capacity.'),example('Find energy to turn 0.10 kg of ice at −20 °C into water at +10 °C. Use the constants in the graph.','Warm ice: Q₁ = 0.10(2100)(20) = 4200 J.','Melt: Q₂ = 0.10(334,000) = 33,400 J. Warm water: Q₃ = 0.10(4180)(10) = 4180 J.','Total = 41,780 J. Most energy here changes phase, so one mcΔT calculation would badly underestimate it.'),example('A slab has κ = 0.20 W/(m·K), A = 2 m², d = 0.04 m, and face temperatures 30 °C and 20 °C. Find power and energy over 60 s.','ΔT = 10 K. P = 0.20(2)(10)/0.04 = 100 W.','Q = PΔt = 100(60) = 6000 J if conditions stay fixed.','Do not report 100 J: power and energy are different quantities.')],
 questions:[question('A temperature-versus-energy graph is twice as steep for sample A as sample B, within one phase. Their heat capacities satisfy…',['C_A = 2C_B','C_A = C_B/2','C_A = C_B','Cannot relate them'],1,'Slope is ΔT/ΔQ = 1/C, so twice the slope means half the heat capacity.'),question('During melting at fixed pressure, heat added primarily…',['Raises temperature','Changes phase','Stops all particle motion','Makes mass zero'],1,'Latent heat changes microscopic configuration while temperature remains at the transition value.'),question('A slab’s thickness and area both double, with other conditions unchanged. Conduction power…',['Doubles','Halves','Stays the same','Quadruples'],2,'P ∝ A/d, so the two factors cancel.')],
 reasoning:[written('Error analysis: “The phase-change plateau means no energy enters because temperature is constant.” Correct it.','Energy continues entering, but it changes phase rather than average kinetic energy associated with temperature. The plateau width on an energy axis corresponds to mL.'),written('Challenge: An insulated cup contains 0.10 kg of ice at 0 °C. It receives 20 kJ. With L_f = 334 kJ/kg, determine its final state.','Full melting needs 33.4 kJ, so 20 kJ cannot melt all the ice. Melted mass is Q/L_f = 20/334 ≈ 0.0599 kg. About 0.0401 kg remains ice; the mixture stays at 0 °C under the stated pressure.')],
 checklist:['Separate warming and phase-change energy.','Find equilibrium using all heat capacities.','Distinguish graph slopes, thermal power, and transferred energy.']},
'9.6': {
 prerequisites:'First-law conservation and thermal equilibrium. A cycle returns to its initial state, so total internal-energy change is zero.',
 opening:'Energy conservation alone would allow a room-temperature object to cool while spontaneously warming a hotter object. Yet that does not occur in ordinary macroscopic systems. The second law specifies the direction that thermal processes favour.',
 sections:[section('Entropy adds a direction to conservation','Entropy S is a state quantity associated with how energy is distributed and how many microscopic arrangements are compatible with a macroscopic state. For an isolated macroscopic system, spontaneous processes do not decrease total entropy. Thermal equilibrium corresponds to maximum entropy under the system’s constraints.','“Disorder” can be a rough metaphor but is too imprecise to solve a question. Instead identify the combined system and reason about energy spreading among accessible microscopic arrangements.'),section('Include the surroundings','One part can lose entropy as it releases heat, while another gains entropy. The second law constrains the total of system and surroundings, not every part independently. A refrigerator can reduce the entropy of its cold compartment while using work and releasing energy to its surroundings.','A reversible process is an ideal limit with no total entropy production. Real irreversible processes such as mixing, friction, or heat flow across a finite temperature difference produce positive total entropy.'),section('Why hot-to-cold transfer is spontaneous','Energy redistribution between many particles favours a common temperature. The colder body gains more entropy from a given transferred energy than the hotter body loses, so total entropy increases during spontaneous heat flow.','Optional quantitative extension: for a reservoir at constant absolute T, ΔS = Q_rev/T can calculate its entropy change. With heat magnitude Q transferred from hot to cold, total change is Q/T_C − Q/T_H > 0. This is enrichment; the core AP objective is qualitative reasoning about the second law.'),section('Heat engines combine both laws','A cyclic engine receives heat magnitude Q_H from a hot reservoir, produces net work W_out, and rejects heat magnitude Q_C to a colder reservoir. First-law balance gives W_out = Q_H − Q_C because ΔU_cycle = 0. Efficiency η = W_out/Q_H is the fraction of input heat converted to work.','For a cyclic engine exchanging heat with a single reservoir, converting all absorbed heat into work with no other effect would violate the second law. A gas can convert all heat to work on one isothermal expansion leg, but returning it to its starting state requires additional transfers. Do not confuse one leg with a complete cycle.'),section('Refrigerators require external work','A refrigerator uses supplied work to move thermal energy from a colder region to a warmer one. It releases more energy to the warm surroundings than it takes from the cold region, because input work also leaves as heat.','Optional extension: the maximum efficiency of an ideal reversible engine between reservoirs is η_Carnot = 1 − T_C/T_H, with kelvin temperatures. Real engines do worse because entropy is produced. This bound is not a claim that every engine reaches it.'),section('Make a defensible AP argument','Name the chosen system, indicate the direction of heat transfer, and explain the combined entropy outcome. Conservation establishes where energy goes; the second law establishes whether the proposed spontaneous direction is feasible.','A claim that “entropy of the cold body increases” is incomplete if the question asks about the whole system. Include the other body and surroundings before drawing a conclusion.')],
 models:[model('ΔS_total ≥ 0','S: entropy (J/K); total includes the system and relevant surroundings.','Spontaneous macroscopic processes in an isolated combination cannot reduce total entropy.','Track all parts. A negative change for one part is permitted if other parts increase by at least as much. Equality describes the ideal reversible limit.','The total must include all exchanges. A local subsystem is not necessarily isolated. Core AP use is qualitative.','An insulated pair approaching common temperature has increasing total entropy despite the hot body losing entropy.'),model('W_out = Q_H − Q_C; η = W_out/Q_H','Q_H and Q_C: positive heat magnitudes per cycle (J); W_out: net work output (J); η: dimensionless efficiency.','Only part of the heat drawn from the hot source becomes useful net work.','First law over a cycle sets ΔU = 0; divide the resulting work balance by Q_H.','Cyclic heat engine with the stated reservoirs. Keep heat magnitudes distinct from signed net heat.','An 800 J input and 500 J rejection give 300 J work and 37.5% efficiency, not 62.5%.')],
 graph:'An engine diagram must show energy into the engine from the hot source, work out, and heat to the cold sink. Arrow labels should satisfy Q_H = W_out + Q_C. A clockwise P–V loop shows positive net work, but it alone does not show reservoir temperatures or guarantee a specified efficiency.',
 examples:[example('An engine absorbs 800 J and rejects 500 J per cycle. Find work and efficiency.','ΔU_cycle = 0, so W_out = 800 − 500 = 300 J.','η = 300/800 = 0.375 = 37.5%.','The 500 J rejected is not useful work. Energy is conserved across all three channels.'),example('A refrigerator removes 200 J from the cold compartment while receiving 80 J of work. How much energy reaches the room?','For one complete cycle ΔU = 0. Input energy is 200 + 80 J.','The warm surroundings receive 280 J.','Local cooling is compatible with the second law because work is supplied and the surroundings are included.'),example('Optional extension: 100 J transfers between reservoirs at 400 K and 300 K. Find total entropy change.','Hot reservoir change = −100/400 = −0.250 J/K. Cold change = +100/300 ≈ +0.333 J/K.','Total ≈ +0.0833 J/K.','The hot part loses entropy, but the isolated combination gains it, consistent with spontaneous transfer.')],
 questions:[question('A cold compartment’s entropy decreases during refrigeration. Which conclusion is valid?',['The second law is always violated','Total system-plus-surroundings entropy must not decrease','The room must lose heat','No work can be supplied'],1,'The second law constrains the total. A subsystem can decrease in entropy with compensating effects outside it.'),question('A cyclic engine absorbs 600 J and outputs 150 J of work. Heat rejected is…',['150 J','450 J','600 J','750 J'],1,'Cycle energy balance gives Q_C = Q_H − W_out = 450 J.'),question('For an isolated system approaching thermal equilibrium, entropy generally…',['Decreases to zero','Increases toward its maximum under the constraints','Must stay unchanged','Depends only on mass'],1,'The equilibrium macrostate is favoured by the greatest accessible number of microscopic arrangements under the constraints.')],
 reasoning:[written('Error analysis: “The first law allows heat to flow either way, so cold-to-hot spontaneous flow is equally likely.” Explain the missing principle.','Conservation alone constrains energy amounts but not direction. The second law requires nondecreasing total entropy. Ordinary spontaneous heat flow from hot to cold increases total entropy; sustained transfer the other way requires supplied work and accounting for surroundings.'),written('Challenge: A proposed cyclic machine absorbs 500 J from one thermal reservoir and outputs 500 J of work, with no other effect. Which laws are satisfied or violated?','Its numerical energy balance satisfies the first law because ΔU_cycle = 0 and input equals output. However, a cycle converting heat from a single reservoir entirely into work with no other effect violates the second law. Conservation is necessary but insufficient.')],
 checklist:['Apply the second law to the whole isolated combination.','Explain why local entropy may decrease.','Use a cycle energy balance and distinguish it from one process leg.']}
};
// A banked road illustrates how an angled contact force can supply circular acceleration.
guidedLessons['2.9'].sections.push(section('A frictionless banked turn','On a road tilted by θ from horizontal, the normal force tilts by θ from vertical toward the turn centre. Resolve it into N cosθ upward and N sinθ inward. With no vertical acceleration, N cosθ = mg; the inward requirement is N sinθ = mv²/r.','Dividing cancels N and m, giving tanθ = v²/(rg). This is the design speed for a frictionless bank. Other speeds generally require friction, whose direction follows the tendency to slip rather than an assumed always-inward rule.'));
guidedLessons['2.9'].models.push(model('tanθ = v²/(rg) (frictionless bank)','θ: bank angle from horizontal; r: turn radius (m); v: design speed (m/s).','Tilting the contact force allows its horizontal component to bend the path while its vertical component supports weight.','Divide N sinθ = mv²/r by N cosθ = mg.','Frictionless bank, no vertical acceleration, horizontal circular path, gravity and normal as the only forces.','Both sides are dimensionless. A steeper bank supports a larger design speed at fixed radius.'));
guidedLessons['9.1'].models.unshift(model('F_avg = Δp/Δt; p_x = mv_x','p_x: signed momentum component [kg·m/s]; Δp: momentum change; Δt: elapsed time (s); F_avg in N.','Momentum tracks how much directed motion a particle carries; a force transfers momentum over time.','An elastic rebound from a stationary wall reverses v_x. The particle change is −2mv_x, so the wall gains impulse +2mv_x. Add wall impulses over many collisions and divide by the measurement interval for average wall force.','Use one axis and a stated interval. For wall pressure, sum only perpendicular transfers. Individual collision forces need not equal the long-time average.','kg·m/s divided by s gives kg·m/s² = N. Tangential motion alone contributes no normal impulse in the ideal smooth-wall model.'));
guidedLessons['9.1'].examples.push(example('A particle of mass 5.0 × 10⁻²⁶ kg approaches a wall normally at 400 m/s and rebounds elastically. Find impulse delivered to the wall.','The particle momentum changes from +mv to −mv, so Δp_particle = −2mv.','Wall impulse is +2mv = 2(5.0 × 10⁻²⁶)(400) = 4.0 × 10⁻²³ N·s.','To find average force on a wall from a stream of atoms, multiply impulse per collision by collisions per second. Then divide by wall area for pressure.'));
